mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM admin_user_roles ur
    JOIN admin_role_permissions rp ON rp.role_id = ur.role_id
    JOIN admin_permissions p ON p.id = rp.permission_id
    WHERE ur.user_id = #{userId, javaType=java.util.UUID, jdbcType=OTHER}
      AND p.resource = #{resource}
      AND p.action = #{action}
)

SELECT EXISTS (
    SELECT 1 FROM host_organizations o WHERE o.owner_user_id = #{userId,javaType=java.util.UUID,jdbcType=OTHER}
    UNION ALL
    SELECT 1 FROM organization_members m
    WHERE m.user_id = #{userId,javaType=java.util.UUID,jdbcType=OTHER}
      AND m.member_status = 'ACTIVE'
      AND (m.valid_from IS NULL OR m.valid_from <= NOW())
      AND (m.valid_until IS NULL OR m.valid_until > NOW())
)

SELECT EXISTS (
    SELECT 1
    FROM admin_resource_owners
    WHERE owner_id = #{ownerId, javaType=java.util.UUID, jdbcType=OTHER}
      AND resource = #{resource}
      AND resource_id = #{resourceId, javaType=java.util.UUID, jdbcType=OTHER}
)

mapper.sql:
WHERE u.deleted_at IS NULL
AND (u.username ILIKE CONCAT('%', #{search}, '%') OR u.email ILIKE CONCAT('%', #{search}, '%') OR u.full_name ILIKE CONCAT('%', #{search}, '%'))
AND u.account_status IN #{item}
AND u.provider IN #{item}
AND EXISTS (SELECT 1 FROM admin_user_roles fur JOIN admin_roles fr ON fr.id = fur.role_id WHERE fur.user_id = u.id AND fr.code IN #{item})

mapper.select:
SELECT u.id, u.username, u.email, u.full_name, u.avatar_url, u.provider, u.account_status, u.language, u.created_at, u.last_login_at, COALESCE(string_agg(DISTINCT r.code, ',' ORDER BY r.code), '') AS roles, (SELECT count(*) FROM user_devices d WHERE d.user_id = u.id AND d.is_active = TRUE) AS device_count, (SELECT count(DISTINCT t.id) FROM trips t LEFT JOIN trip_members tm ON tm.trip_id = t.id WHERE (t.owner_id = u.id OR tm.user_id = u.id) AND COALESCE(t.is_deleted, false) = false) AS trip_count, (SELECT count(*) FROM user_checkins c WHERE c.user_id = u.id) AS checkin_count, (SELECT count(*) FROM user_reviews rv WHERE rv.user_id = u.id) AS review_count, (SELECT count(*) FROM place_contributions pc WHERE pc.user_id = u.id) AS contribution_count FROM users u LEFT JOIN admin_user_roles ur ON ur.user_id = u.id LEFT JOIN admin_roles r ON r.id = ur.role_id
GROUP BY u.id
LIMIT #{limit} OFFSET #{offset}

mapper.insert:
INSERT INTO admin_user_roles(user_id, role_id) SELECT #{userId, javaType=java.util.UUID, jdbcType=OTHER}, id FROM admin_roles WHERE code IN
#{code}
ON CONFLICT DO NOTHING

mapper.update:
UPDATE media_assets
SET deleted_at = NOW()
WHERE id = #{id, javaType=java.util.UUID, jdbcType=OTHER}

mapper.select:
SELECT t.id, t.name, t.destination, t.status, t.visibility, t.owner_id, t.created_at, u.username, (SELECT count(*) FROM activities a WHERE a.trip_id = t.id) AS activity_count, (SELECT count(*) FROM trip_members m WHERE m.trip_id = t.id) AS member_count FROM trips t LEFT JOIN users u ON u.id = t.owner_id WHERE COALESCE(t.is_deleted, false) = false AND (t.name ILIKE CONCAT('%', #{search}, '%') OR t.destination ILIKE CONCAT('%', #{search}, '%') OR u.username ILIKE CONCAT('%', #{search}, '%'))
AND t.status IN #{item}
AND t.visibility IN #{item}
ORDER BY
t.name t.destination u.username activity_count member_count t.created_at
DESC NULLS LAST ASC NULLS LAST
, t.id DESC LIMIT #{limit} OFFSET #{offset}
